CITE_QR = ("« When Revealed ... If you cannot, resolve the \"Special\" ability on the SETTING environment » : `QuandRevele` "
           "(imperial_guard/__init__.py : WhenThisRevealed + ResolveSpecialAbility, modele baxter_stockman ResoudreLeSpecial)")
PIEGE_QR = ("« If you CANNOT » = aucune carte a defausser (le sbire n'a aucun autre effet) ; « YOU » = le joueur a qui il est revele ; "
            "le Special vise l'environnement SETTING EN JEU")
NB_8BIS = "NON (le sbire entre en jeu, ses cartes defaussees quittent des zones standard)"


def _sbire(nom, ref, piege, pv, sch, atk, boost, note="", plateau=NB_8BIS):
    return (nom, CITE_QR + " ; " + ref, PIEGE_QR + " ; " + piege,
            f"PV {pv} (pastille orange), MNG {sch}, ATQ {atk}, {boost} icone(s) de boost. Identiques desc / script / scan.",
            "NON", plateau, note)


